{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Compound 6, a morpholine-containing anilino-fused heteroaromatic analogue, showed high brain penetration in rat with a B/P ratio of 2.4.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Compound 4, a close structural analogue with the same morpholine-sulfonyl anilino phenotype, showed a B/P ratio of 3.0 in rat, confirming high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "ABM300, a lipophilic heteroaromatic anilide, achieved a brain/plasma AUC ratio of 0.77 with measurable brain concentrations in mice, indicating CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "A-412997 partitioned rapidly into rat brain with brain/plasma ratios greater than 1 after subcutaneous dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "AZ3303 displayed good brain-penetrating properties and modulated brain Aβ42 levels after oral dosing in mice.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "[18F]FNDP showed high and rapid brain uptake in baboon PET imaging.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Compound 5 reached the brain and tended to accumulate there in mouse pharmacokinetic experiments.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "PD156707 crossed the blood-brain barrier with measurable CSF levels in dogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Imatinib brain uptake is restricted by P-gp/BCRP efflux in mice, indicating poor CNS penetration for that specific, less lipophilic chemotype.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer direct in vivo brain-penetration measurements from structurally related morpholine/anilino-heteroaromatic and lipophilic CNS-active compounds support meaningful CNS access. The imatinib poor-penetration data represent a single, less lipophilic chemotype and are outweighed by the convergent supportive evidence.",
  "evidence_gaps": [
    "No direct experimental brain or CSF concentration data for the exact query molecule.",
    "Efflux liability of the query at P-gp/BCRP has not been directly measured.",
    "Unbound brain concentrations are not reported for the supportive analogues, so free brain exposure remains uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

